package com.autumnharvestc.server.sync;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

class SyncCheckCancellationTest extends SyncCheckHttpFixture {
    @org.springframework.beans.factory.annotation.Autowired SyncCheckWorker worker;
    @ParameterizedTest @ValueSource(strings={"foreign-actor","foreign-scope","deny","source-edited"})
    void cancellationKeepsCurrentAuthorityScopeAndStableCheckIdentity(String variant) throws Exception {
        checkToCandidate(createUrlSource("/fast"));String barrier=UUID.randomUUID().toString();var source=createUrlSource("/blocked/"+barrier);var actor=variant.equals("foreign-actor")?f.owner():editor();var accepted=body(sourceRequest("POST","/sources/"+source.path("id").asText()+"/checks",actor,checkBody()).andExpect(status().isAccepted()));String id=accepted.path("checkId").asText();awaitNode("received-"+barrier);
        try{
            if(variant.equals("foreign-scope")){String other=anotherProject();mvc.perform(post(f.workspaceUrl()+"/projects/"+other+"/sync/checks/"+id+"/cancel").header("Authorization","Bearer "+editor().token()).contentType("application/json").content("{}")).andExpect(status().isNotFound());}
            else if(variant.equals("foreign-actor"))sourceRequest("POST","/checks/"+id+"/cancel",editor(),json.createObjectNode()).andExpect(status().isForbidden());
            else if(variant.equals("deny")){capabilities(null,Map.of("sync.check","deny"));sourceRequest("POST","/checks/"+id+"/cancel",editor(),json.createObjectNode()).andExpect(status().isForbidden());}
            else sourceRequest("PUT","/sources/"+source.path("id").asText(),f.owner(),sourceUpdateBody(source).put("expectedAssetVersion","2")).andExpect(status().isOk());
            sourceRequest("POST","/checks/"+id+"/cancel",f.owner(),json.createObjectNode()).andExpect(status().isAccepted());awaitNode("collected-"+barrier);assertNodeCollected("cancel-current-authority");assertThat(awaitCheckAs(id,f.owner()).path("state").asText()).isEqualTo("cancelled");var replay=body(sourceRequest("POST","/checks/"+id+"/cancel",f.owner(),json.createObjectNode()).andExpect(status().isAccepted()));assertThat(replay.path("checkId").asText()).isEqualTo(id);assertThat(replay.path("state").asText()).isEqualTo("cancelled");
        }finally{release(barrier);}
    }
    @Test void hostExecutionSlotsBoundJavaWaitersAndLeaveExcessChecksDurablyQueued() throws Exception {
        checkToCandidate(createUrlSource("/fast"));String barrier=UUID.randomUUID().toString();var source=createUrlSource("/blocked/"+barrier);var ids=new java.util.ArrayList<String>();
        try{ids.add(submit(source,checkBody()).path("checkId").asText());awaitNode("received-"+barrier);for(int i=0;i<4;i++)ids.add(submit(source,checkBody()).path("checkId").asText());long until=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(5);while(System.nanoTime()<until){int waiting=jdbc.queryForObject("SELECT COUNT(*) FROM sync_checks WHERE project_id=? AND state='waiting'",Integer.class,Long.parseLong(f.project()));if(waiting>=3)break;Thread.sleep(10);}
            var owned=(java.util.Map<?,?>)org.springframework.test.util.ReflectionTestUtils.getField(worker,"work");assertThat(owned.size()).isLessThanOrEqualTo(4);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sync_checks WHERE project_id=? AND state IN ('queued','waiting')",Integer.class,Long.parseLong(f.project()))).isGreaterThanOrEqualTo(1);
            // Waiting is durable after pre-execution SYNC_BUSY and must yield a Java slot to another project.
            String other=anotherProject(),otherUrl=f.workspaceUrl()+"/projects/"+other;var delta=json.createObjectNode().put("format","contract-files-v1").put("contractProjectId","00000000-0000-4000-8000-000000000070").put("expectedVersion","0");delta.set("changes",node.info.path("files"));delta.set("deletes",json.createArrayNode());mvc.perform(put(otherUrl+"/assets").header("Authorization","Bearer "+f.owner().token()).contentType("application/json").content(delta.toString())).andExpect(status().isOk());String otherBarrier=UUID.randomUUID().toString();var otherSource=body(mvc.perform(post(otherUrl+"/sync/sources").header("Authorization","Bearer "+f.owner().token()).contentType("application/json").content(write(sourceBody("url").put("url",node.info.path("origin").asText()+"/blocked/"+otherBarrier)).put("expectedAssetVersion","1").toString())).andExpect(status().isCreated()));var otherCheck=body(mvc.perform(post(otherUrl+"/sync/sources/"+otherSource.path("id").asText()+"/checks").header("Authorization","Bearer "+editor().token()).contentType("application/json").content(checkBody().put("expectedAssetVersion","1").toString())).andExpect(status().isAccepted()));
            try{awaitNode("received-"+otherBarrier);assertThat(nodeFacts("fair-other-project-start").path("held").asInt()).isEqualTo(2);}finally{mvc.perform(post(otherUrl+"/sync/checks/"+otherCheck.path("checkId").asText()+"/cancel").header("Authorization","Bearer "+editor().token()).contentType("application/json").content("{}")).andExpect(status().isAccepted());release(otherBarrier);awaitNode("collected-"+otherBarrier);}
        }finally{for(String id:ids)sourceRequest("POST","/checks/"+id+"/cancel",editor(),json.createObjectNode()).andExpect(status().isAccepted());release(barrier);awaitNode("collected-"+barrier);}
    }
    @Test void cancelBodyIsStrictOnAnOtherwiseLegalCompletedCheck() throws Exception {
        var source=createUrlSource("/fast");var accepted=submit(source,checkBody());assertThat(awaitCheck(accepted.path("checkId").asText()).path("state").asText()).isEqualTo("succeeded");sourceRequest("POST","/checks/"+accepted.path("checkId").asText()+"/cancel",editor(),json.createObjectNode().put("url","not-a-field")).andExpect(status().isBadRequest());
    }
    @Test void freshBackendStartupRetainsUnknownNodeOwnershipAndFencesTheOldWorker() throws Exception {
        checkToCandidate(createUrlSource("/fast"));String barrier=UUID.randomUUID().toString();var source=createUrlSource("/blocked/"+barrier);var first=submit(source,checkBody());awaitNode("received-"+barrier);int starts=sourceHostCalls();
        var settings=new java.util.LinkedHashMap<String,Object>();settings.put("spring.datasource.url",DATABASE_URL);settings.put("server.port",0);settings.put("apicc.server.allow-registration",true);settings.put("apicc.collaboration.runtime.enabled",true);settings.put("apicc.collaboration.runtime.base-url",node.info.path("url").asText());settings.put("apicc.collaboration.runtime.secret-file",node.info.path("secretFile").asText());settings.put("apicc.execution.materials.master-key-file",key.toString());
        try(var restarted=new org.springframework.boot.builder.SpringApplicationBuilder(com.autumnharvestc.server.ApiccServerApplication.class).run(settings.entrySet().stream().map(entry->"--"+entry.getKey()+"="+entry.getValue()).toArray(String[]::new))){
            int port=((org.springframework.boot.web.servlet.context.ServletWebServerApplicationContext)restarted).getWebServer().getPort();var response=java.net.http.HttpClient.newHttpClient().send(java.net.http.HttpRequest.newBuilder(java.net.URI.create("http://127.0.0.1:"+port+f.projectUrl()+"/sync/checks/"+first.path("checkId").asText())).header("Authorization","Bearer "+editor().token()).GET().build(),java.net.http.HttpResponse.BodyHandlers.ofString());assertThat(response.statusCode()).isEqualTo(200);var recovered=json.readTree(response.body());assertThat(recovered.path("state").asText()).isEqualTo("lost");assertThat(recovered.path("reasonCode").asText()).isEqualTo("server-restarted");assertThat(sourceHostCalls()).isEqualTo(starts);
            var second=submit(source,checkBody());assertThat(awaitWaitingOrTerminal(second.path("checkId").asText()).path("state").asText()).isEqualTo("waiting");release(barrier);awaitNode("collected-"+barrier);awaitStarts(starts+1);release(barrier);assertThat(awaitCheck(second.path("checkId").asText()).path("state").asText()).isEqualTo("succeeded");assertThat(awaitCheck(first.path("checkId").asText()).path("candidateId").isNull()).isTrue();
        }finally{release(barrier);}
    }
    @Test void cancellingAnActualReadCollectsItsSocketBeforeTheNextReadSucceeds() throws Exception {
        checkToCandidate(createUrlSource("/fast"));String barrier=UUID.randomUUID().toString();var source=createUrlSource("/blocked/"+barrier);var accepted=submit(source,checkBody());awaitNode("received-"+barrier);
        try{assertThat(nodeFacts("cancel-owned").path("held").asInt()).isEqualTo(1);sourceRequest("POST","/checks/"+accepted.path("checkId").asText()+"/cancel",editor(),json.createObjectNode()).andExpect(status().isAccepted());awaitNode("collected-"+barrier);assertNodeCollected("cancel-collected");assertThat(awaitCheck(accepted.path("checkId").asText()).path("state").asText()).isEqualTo("cancelled");int starts=sourceHostCalls();var next=submit(source,checkBody());awaitStarts(starts+1);release(barrier);assertThat(awaitCheck(next.path("checkId").asText()).path("state").asText()).isEqualTo("succeeded");assertNodeCollected("cancel-next-success");}finally{release(barrier);}
    }
    @ParameterizedTest @ValueSource(strings={"same-source","project-slot"})
    void definitiveBusyWaitsWithoutStartingAnotherSourceRead(String kind) throws Exception {
        checkToCandidate(createUrlSource("/fast"));String barrier=UUID.randomUUID().toString();var source=createUrlSource("/blocked/"+barrier);var first=submit(source,checkBody());awaitNode("received-"+barrier);int starts=sourceHostCalls();var other=kind.equals("same-source")?source:createUrlSource("/cache");var second=submit(other,checkBody());
        try{var state=awaitWaitingOrTerminal(second.path("checkId").asText());assertThat(state.path("state").asText()).withFailMessage(state.toString()).isEqualTo("waiting");assertThat(state.path("reasonCode").asText()).isEqualTo("source-busy");assertThat(sourceHostCalls()).isEqualTo(starts);}finally{release(barrier);}
        assertThat(awaitCheck(first.path("checkId").asText()).path("state").asText()).isEqualTo("succeeded");
        if(kind.equals("same-source"))awaitStarts(starts+1); // A fresh admitted invocation is independently owned.
        if(kind.equals("same-source"))release(barrier);
        var completed=awaitCheck(second.path("checkId").asText());assertThat(completed.path("state").asText()).withFailMessage(completed.toString()).isEqualTo("succeeded");assertThat(sourceHostCalls()).isEqualTo(starts+1);
    }
    @Test void transportLossDoesNotRepeatAReadAndNewCheckWaitsForActualNodeCollection() throws Exception {
        checkToCandidate(createUrlSource("/fast"));String barrier=UUID.randomUUID().toString();var source=createUrlSource("/blocked/"+barrier);releaseControl("drop-next");var first=submit(source,checkBody());awaitNode("received-"+barrier);awaitNode("transport-lost");int starts=sourceHostCalls();
        try{var lost=awaitCheck(first.path("checkId").asText());assertThat(lost.path("state").asText()).withFailMessage(lost.toString()).isEqualTo("lost");assertThat(lost.path("reasonCode").asText()).isEqualTo("runtime-unavailable");assertThat(sourceHostCalls()).isEqualTo(starts);var second=submit(source,checkBody());var waiting=awaitWaitingOrTerminal(second.path("checkId").asText());assertThat(waiting.path("state").asText()).isEqualTo("waiting");assertThat(sourceHostCalls()).isEqualTo(starts);release(barrier);awaitNode("collected-"+barrier);awaitStarts(starts+1);release(barrier);assertThat(awaitCheck(second.path("checkId").asText()).path("state").asText()).isEqualTo("succeeded");assertThat(awaitCheck(first.path("checkId").asText()).path("candidateId").isNull()).isTrue();}finally{release(barrier);}
    }
    @ParameterizedTest @ValueSource(strings={"project","workspace"})
    void owningScopeDeletionCancelsTheActualReadAndLateWorkerCannotResurrectRows(String scope) throws Exception {
        checkToCandidate(createUrlSource("/fast"));String barrier=UUID.randomUUID().toString();var source=createUrlSource("/blocked/"+barrier);submit(source,checkBody());awaitNode("received-"+barrier);
        try{assertThat(nodeFacts("delete-owned").path("held").asInt()).isEqualTo(1);mvc.perform(delete(scope.equals("workspace")?f.workspaceUrl():f.projectUrl()).header("Authorization","Bearer "+f.owner().token())).andExpect(status().isNoContent());awaitNode("collected-"+barrier);assertNodeCollected("delete-collected");long until=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(5);while(System.nanoTime()<until&&!((java.util.Map<?,?>)org.springframework.test.util.ReflectionTestUtils.getField(worker,"work")).isEmpty())Thread.sleep(10);assertThat((java.util.Map<?,?>)org.springframework.test.util.ReflectionTestUtils.getField(worker,"work")).isEmpty();for(String table:List.of("sync_checks","sync_candidates","sync_history","sync_operations","sync_sources","sync_policies"))assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE workspace_id=? AND project_id=?",Integer.class,Long.parseLong(f.workspace()),Long.parseLong(f.project()))).isZero();}finally{release(barrier);}
    }
    com.fasterxml.jackson.databind.JsonNode awaitWaitingOrTerminal(String id) throws Exception {long until=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(6);while(System.nanoTime()<until){var check=body(sourceRequest("GET","/checks/"+id,editor(),null).andExpect(status().isOk()));if(Set.of("waiting","succeeded","failed","lost","cancelled").contains(check.path("state").asText()))return check;Thread.sleep(10);}throw new AssertionError("No admission state");}
    void releaseControl(String path) throws Exception {java.net.http.HttpClient.newHttpClient().send(java.net.http.HttpRequest.newBuilder(java.net.URI.create(node.info.path("origin").asText()+"/"+path)).GET().build(),java.net.http.HttpResponse.BodyHandlers.discarding());}
    void awaitStarts(int count) throws Exception {long until=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(6);while(System.nanoTime()<until){if(sourceHostCalls()>=count)return;Thread.sleep(10);}throw new AssertionError("New source did not actually start");}
    com.fasterxml.jackson.databind.JsonNode nodeFacts(String phase) throws Exception {var response=java.net.http.HttpClient.newHttpClient().send(java.net.http.HttpRequest.newBuilder(java.net.URI.create(node.info.path("origin").asText()+"/control")).GET().build(),java.net.http.HttpResponse.BodyHandlers.ofString());var facts=(com.fasterxml.jackson.databind.node.ObjectNode)json.readTree(response.body());facts.put("phase",phase);try(var markers=java.nio.file.Files.list(node.directory.resolve("private/.apicc-sync-owners"))){facts.put("markers",markers.count());}try(var privateEntries=java.nio.file.Files.list(node.directory.resolve("private"))){facts.put("readOwners",privateEntries.filter(path->path.getFileName().toString().startsWith("read-")).count());}System.out.println("T9_NODE_FACTS "+facts);return facts;}
    void assertNodeCollected(String phase) throws Exception {long until=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(6);while(System.nanoTime()<until){var facts=nodeFacts(phase);if(facts.path("held").asInt()==0&&facts.path("markers").asInt()==0){assertThat(facts.path("retained").asInt()).isZero();assertThat(facts.path("readOwners").asInt()).isZero();return;}Thread.sleep(10);}throw new AssertionError("Actual Node ownership not collected");}
}
